SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 63 AND p.anchor_year_group BETWEEN 58 AND 68 AND l.itemid = 817981 AND l.value > 0.04;